package br.ucb.claquete.controller;
import br.ucb.claquete.service.AcervoJdbcService; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/filmes") public class FilmeController { private final AcervoJdbcService s; public FilmeController(AcervoJdbcService s){this.s=s;} @GetMapping public List<Map<String,Object>> listar(@RequestParam(required=false)String titulo,@RequestParam(required=false)Integer anoMin,@RequestParam(required=false)Integer anoMax,@RequestParam(required=false)String genero){return s.filmes(titulo,anoMin,anoMax,genero);}@GetMapping("/{id}")public Map<String,Object> buscar(@PathVariable int id){return s.filme(id);}@PostMapping public ResponseEntity<Map<String,Object>> criar(@RequestBody Map<String,Object> r){Map<String,Object>x=s.criarFilme(r);return ResponseEntity.created(URI.create("/api/filmes/"+x.get("id"))).body(x);}@PostMapping("/ficha-tecnica")public ResponseEntity<Map<String,Object>> criarFichaTecnica(@RequestBody Map<String,Object> r){Map<String,Object>x=s.criarFichaTecnica(r);return ResponseEntity.created(URI.create("/api/filmes/"+x.get("id"))).body(x);}@PutMapping("/{id}")public Map<String,Object> atualizar(@PathVariable int id,@RequestBody Map<String,Object>r){return s.atualizarFilme(id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void excluir(@PathVariable int id){s.excluirFilme(id);}}
